/**
 * The application frame (`design/archetypes/app-shell.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/app-shell.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, createUniqueId, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'
import { Dynamic } from 'solid-js/web'

import {
  PageTransition,
  agentMember,
  anchorFocusReturns,
  arriveAtPage,
  claimSlot,
  classes,
  createCell,
  createDerived,
  createKept,
  currentRailDestination,
  elementRef,
  focusFromScript,
  goToRailDestination,
  ownerContext,
  provide,
  railDestinations,
  resolveSlot,
  scope,
  watchEffect,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/archetypes/app-shell.module.css'
import transitions from '@polymorph/recipes/conventions/page-transitions.module.css'
import Button from '../controls/Button'
import type { AppShellNavGroupProps } from './AppShellNavGroup'
import type { AppShellNavItemProps } from './AppShellNavItem'
import type { AppShellUserCardProps } from './AppShellUserCard'

export type NavItemProps = AppShellNavItemProps

export type NavGroupProps = AppShellNavGroupProps

export type UserCardProps = AppShellUserCardProps

export interface AppShellTopbar {
  leading?: JSX.Element
  trailing?: JSX.Element
}

export interface AppShellProps {
  /**
   * One `Banner`: the notice that holds on every page until its cause ends. It takes a row of
   * its own across the frame, above the rail and the topbar, so the rail and the content region
   * shorten by its height and nothing scrolls under it.
   */
  banner?: JSX.Element
  brand?: JSX.Element
  children: JSX.Element
  collapsed?: boolean
  /**
   * A bounded, responsive reading surface for pages composed directly from controls.
   */
  contentLayout?: 'full' | 'page'
  defaultCollapsed?: boolean
  /**
   * A floating layer pinned to the bottom of the content region, for a product's always-present
   * control (a prompt, a player, a selection bar). It shares the content area's grid cell
   * instead of taking its own row. So it floats over the page instead of shortening it, and it
   * re-centres on the content when the rail collapses, because the cell moves. The layer ignores
   * the pointer and its children re-enable it, so the space around the floating control still
   * belongs to the page underneath. A dock overlays content, so a page with a dock leaves room
   * at its bottom.
   */
  dock?: JSX.Element
  /**
   * Application-localized navigation names.
   */
  messages?: {
    primaryNavigation: string
    expandSidebar: string
    collapseSidebar: string
    closeNavigation: string
    openNavigation: string
    skipToContent?: string
  }
  /**
   * Where the navigation is drawn at frame widths. `'rail'` is the column at the frame's start.
   * `'top'` lays the same navigation along the frame's top row, before the topbar's slots, and
   * the rail's width collapse does not apply. Below the drawer breakpoint both are the same
   * drawer.
   */
  navigation?: 'top' | 'rail'
  onCollapsedChange?: (collapsed: boolean) => void
  pending?: boolean
  /**
   * Nav content, from the vocabulary.
   */
  sidebar: JSX.Element
  sidebarFooter?: JSX.Element
  topbar?: AppShellTopbar
  /**
   * Presentation identity for page arrivals; does not key or remount children. A new key also
   * closes the small-viewport drawer.
   */
  transitionKey?: string
}

/** What AppShell hands its compound parts. */
export interface AppShellOwner {
  readonly collapsed: unknown
}

/** The application frame. */
export default function AppShell(given: AppShellProps): JSX.Element {
  const props = mergeProps(
    { contentLayout: 'full', navigation: 'rail', pending: false } as Defaults<
      AppShellProps,
      'contentLayout' | 'navigation' | 'pending'
    >,
    claimSlot(given),
  )
  return scope(() => {
    const topbarKept = createKept(() => props.topbar)
    provide(ownerContext<AppShellOwner>('AppShell'), {
      get collapsed() {
        return isCollapsed.value
      },
    })
    const uid = createUniqueId()
    const announcer = elementRef<HTMLElement>()
    const drawerToggle = elementRef<HTMLElement>()
    const frame = elementRef<HTMLElement>()
    const rail = elementRef<HTMLElement>()
    const railToggle = elementRef<HTMLElement>()
    const bannerSlot = resolveSlot(() => props.banner)
    const brandSlot = resolveSlot(() => props.brand)
    const dockSlot = resolveSlot(() => props.dock)
    const sidebarFooterSlot = resolveSlot(() => props.sidebarFooter)
    const uncontrolled = createCell(props.defaultCollapsed ?? false)
    const drawer = createCell(false)
    const held = createDerived(() => props.collapsed ?? uncontrolled.value)
    const isCollapsed = createDerived(() => props.navigation === 'rail' && held.value)
    const say = createDerived(
      () =>
        props.messages ?? {
          primaryNavigation: 'Primary',
          expandSidebar: 'Expand sidebar',
          collapseSidebar: 'Collapse sidebar',
          closeNavigation: 'Close navigation',
          openNavigation: 'Open navigation',
        },
    )
    const toggle = createDerived(() => (): void => {
      const next = !held.value
      uncontrolled.value = next
      props.onCollapsedChange?.(next)
    })
    const effect1 = () => {
      void (drawer.value
        ? rail.value?.focus()
        : drawerToggle.value &&
          anchorFocusReturns(drawerToggle.value, rail.value ?? null) &&
          drawerToggle.value.querySelector<HTMLElement>('button')?.focus())
    }
    watchEffect(
      createMemo(() => drawer.value),
      effect1,
      false,
    )
    let release2: (() => void) | undefined
    const effect2 = () => {
      release2?.()
      const listener = ($event: KeyboardEvent) => {
        void (
          drawer.value &&
          $event.key === 'Escape' &&
          !$event.defaultPrevented &&
          (drawer.value = false)
        )
      }
      document.addEventListener('keydown', listener)
      release2 = () => document.removeEventListener('keydown', listener)
    }
    onMount(effect2)
    onCleanup(() => release2?.())
    let release3: (() => void) | undefined
    const effect3 = () => {
      release3?.()
      const run = () => {
        void (
          drawer.value &&
          drawerToggle.value &&
          window.getComputedStyle(drawerToggle.value).display === 'none' &&
          (drawer.value = false)
        )
      }
      const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
      for (const element of [drawerToggle.value]) if (element) resize?.observe(element)
      release3 = () => {
        resize?.disconnect()
      }
      run()
    }
    onMount(effect3)
    onCleanup(() => release3?.())
    const effect4 = () => {
      drawer.value = false
    }
    watchEffect(
      createMemo(() => props.transitionKey),
      effect4,
      false,
    )
    let release5: (() => void) | undefined
    const effect5 = () => {
      release5?.()
      const ran = arriveAtPage(
        frame.value?.querySelector<HTMLElement>(':scope > main'),
        announcer.value,
        props.transitionKey,
        props.pending,
      )
      release5 = () => {
        ran()
      }
    }
    watchEffect(
      createMemo(() => [props.transitionKey, props.pending]),
      effect5,
      true,
    )
    onCleanup(() => release5?.())
    let release6: (() => void) | undefined
    const effect6 = () => {
      release6?.()
      const ran = agentMember({
        member: 'AppShell',
        element: () => rail.value,
        state: () => ({
          collapsed: isCollapsed.value,
          open: drawer.value,
          destinations: railDestinations(rail.value, {
            item: styles.navItem,
            label: styles.navLabel,
          }),
          current: currentRailDestination(rail.value, {
            item: styles.navItem,
            label: styles.navLabel,
          }),
        }),
        actions: {
          collapse: () =>
            (() => {
              if (!railToggle.value || window.getComputedStyle(railToggle.value).display === 'none')
                throw new Error(
                  'The rail has no width to change here: below the breakpoint it is a drawer, and with the navigation on top there is no rail.',
                )
              if (!held.value) toggle.value()
            })(),
          expand: () =>
            (() => {
              if (!railToggle.value || window.getComputedStyle(railToggle.value).display === 'none')
                throw new Error(
                  'The rail has no width to change here: below the breakpoint it is a drawer, and with the navigation on top there is no rail.',
                )
              if (held.value) toggle.value()
            })(),
          open: () =>
            (() => {
              if (
                !drawerToggle.value ||
                window.getComputedStyle(drawerToggle.value).display === 'none'
              )
                throw new Error(
                  'There is no drawer here: above the breakpoint the navigation is drawn beside the page or along its top.',
                )
              drawer.value = true
            })(),
          close: () =>
            (() => {
              if (
                !drawerToggle.value ||
                window.getComputedStyle(drawerToggle.value).display === 'none'
              )
                throw new Error(
                  'There is no drawer here: above the breakpoint the navigation is drawn beside the page or along its top.',
                )
              drawer.value = false
            })(),
          go: {
            argument: 'id',
            run: (value) =>
              goToRailDestination(
                rail.value,
                { item: styles.navItem, label: styles.navLabel },
                value,
              ),
          },
        },
        withholds: () => [railToggle.value, drawerToggle.value],
      })
      release6 = () => {
        ran()
      }
    }
    onMount(effect6)
    onCleanup(() => release6?.())
    return (
      <div
        class={styles.shell}
        data-collapsed={isCollapsed.value ? '' : undefined}
        data-navigation={props.navigation === 'top' ? 'top' : undefined}
        data-drawer={drawer.value ? '' : undefined}
        data-member="app-shell"
        ref={frame.attach}
      >
        {/* skip */}
        <a
          class={styles.skip}
          href="#content"
          inert={drawer.value}
          onclick={() => focusFromScript(frame.value?.querySelector<HTMLElement>(':scope > main'))}
        >
          {say.value.skipToContent ?? 'Skip to content'}
        </a>
        {bannerSlot.filled() ? (
          <div class={styles.banner} inert={drawer.value}>
            {bannerSlot()}
          </div>
        ) : null}
        {/* sidebar */}
        <nav
          class={styles.sidebar}
          id={uid}
          aria-label={say.value.primaryNavigation}
          tabindex="-1"
          ref={rail.attach}
        >
          {/* railHead */}
          <div class={styles.railHead}>
            {brandSlot.filled() ? <div class={styles.brand}>{brandSlot()}</div> : null}
            {/* toggle */}
            <div class={styles.toggle} ref={railToggle.attach}>
              <Button
                variant="ghost"
                tone="neutral"
                size="sm"
                iconOnly={true}
                icon={isCollapsed.value ? 'next' : 'previous'}
                label={isCollapsed.value ? say.value.expandSidebar : say.value.collapseSidebar}
                onClick={() => toggle.value()}
              />
            </div>
          </div>
          {/* nav */}
          <div class={styles.nav}>{props.sidebar}</div>
          {sidebarFooterSlot.filled() ? (
            <div class={styles.sidebarFooter}>{sidebarFooterSlot()}</div>
          ) : null}
        </nav>
        {/* topbar */}
        <header class={styles.topbar} inert={drawer.value}>
          {/* leading */}
          <div class={styles.topbarSlot}>
            {/* drawerToggle */}
            <span class={styles.drawerToggle} ref={drawerToggle.attach}>
              <Button
                variant="ghost"
                tone="neutral"
                size="sm"
                iconOnly={true}
                icon="menu"
                label={drawer.value ? say.value.closeNavigation : say.value.openNavigation}
                expanded={drawer.value}
                aria-controls={uid}
                onClick={() => (drawer.value = !drawer.value)}
              />
            </span>
            {topbarKept.value?.leading !== undefined ? topbarKept.value?.leading : null}
          </div>
          {/* trailing */}
          <div class={styles.topbarSlot}>
            {topbarKept.value?.trailing !== undefined ? topbarKept.value?.trailing : null}
          </div>
        </header>
        {drawer.value ? (
          <button
            class={styles.scrim}
            type="button"
            aria-label={say.value.closeNavigation}
            onclick={() => (drawer.value = false)}
          />
        ) : null}
        {/* content */}
        <Dynamic
          component={PageTransition}
          class={classes(
            styles.content,
            props.transitionKey !== undefined ? transitions.page : undefined,
          )}
          as="main"
          id="content"
          inert={drawer.value}
          transitionKey={props.transitionKey}
          pending={props.pending}
          ribbon={transitions.indicator}
        >
          {props.contentLayout === 'page' ? (
            <div class={styles.page}>{props.children}</div>
          ) : (
            props.children
          )}
        </Dynamic>
        {dockSlot.filled() ? (
          <div class={styles.dock} inert={drawer.value}>
            {dockSlot()}
          </div>
        ) : null}
        {/* announcer */}
        <div class={styles.announcer} role="status" ref={announcer.attach} />
      </div>
    )
  })
}
